partial class VectorShape {
 public string GroupId="";public float Taper;public bool Filled;public string Kind;public List<PointF> Points=new List<PointF>();public Color Colour;public float Width=5,Opacity=1;
 public RectangleF Bounds(){if(Points.Count<2)return RectangleF.Empty;using(var path=Path()){var rect=path.GetBounds();rect.Inflate(Width/2+3,Width/2+3);return rect;}}
 public VectorShape Copy(){return new VectorShape{CornerRadius=CornerRadius,ContourStarts=(int[])ContourStarts.Clone(),TextContent=TextContent,TextFamily=TextFamily,TextStyle=TextStyle,TextPoints=TextPoints,TextDpi=TextDpi,GroupId=GroupId,Fill=Fill.Copy(),Handles=CopyHandles(),Taper=Taper,Kind=Kind,Filled=Filled,Points=new List<PointF>(Points),Colour=Colour,Width=Width,Opacity=Opacity};}
 public GraphicsPath Path(){if(Kind=="Compound")return CompoundPath();if(Kind=="Text")return TextPath();if(CornerRadius>0&&CanRadius)return RoundedPath();if(Handles.Count>0&&HasPointHandles)return HandlePath();var p=new GraphicsPath();if(Points.Count<2)return p;if(Kind=="Ellipse"){PointF c,u,v;EllipseAxes(out c,out u,out v);p.AddEllipse(-1,-1,2,2);using(var m=new Matrix(u.X,u.Y,v.X,v.Y,c.X,c.Y))p.Transform(m);}else if(Kind=="Closed curve"&&Points.Count>=3)p.AddClosedCurve(Points.ToArray(),.5522848f);else if(Kind=="Curvature pen"){if(Points.Count==2)p.AddLine(Points[0],Points[1]);else p.AddCurve(Points.ToArray(),.5f);}else if(Kind=="Polygon"&&Points.Count>=3)p.AddPolygon(Points.ToArray());else p.AddLines(Points.ToArray());return p;}
 public void Draw(Graphics g){if(Points.Count<2)return;using(var path=Path())using(var pen=new Pen(Color.FromArgb((int)(Opacity*255),Colour),Width)){if(CanFill&&Fill.Mode!=0){using(var brush=Fill.Brush(path,Opacity))g.FillPath(brush,path);}pen.StartCap=pen.EndCap=LineCap.Round;pen.LineJoin=Kind=="Polyline"?LineJoin.Miter:LineJoin.Round;if(Taper>0&&CanTaper){using(var outline=TaperPath())using(var brush=new SolidBrush(pen.Color))g.FillPath(brush,outline);}else if(Filled){using(var brush=new SolidBrush(pen.Color))g.FillPath(brush,path);}else g.DrawPath(pen,path);}}
 public bool Hit(PointF point,float tolerance){if(Points.Count<2)return false;if(HasFill){using(var fillPath=Path())if(fillPath.IsVisible(point))return true;}if(Taper>0&&CanTaper){using(var outline=TaperPath())using(var hitPen=new Pen(Color.Black,tolerance*2))return outline.IsVisible(point)||outline.IsOutlineVisible(point,hitPen);}using(var p=Path())using(var pen=new Pen(Color.Black,Width+tolerance*2))return (Filled&&p.IsVisible(point))||p.IsOutlineVisible(point,pen);}
 public void Write(BinaryWriter w){w.Write(Kind);w.Write(Filled);w.Write(Colour.ToArgb());w.Write(Width);w.Write(Opacity);w.Write(Taper);w.Write(Points.Count);foreach(var p in Points){w.Write(p.X);w.Write(p.Y);}WriteHandles(w);}
 public static VectorShape Read(BinaryReader r,bool filledField=false,bool taperField=false,bool handlesField=false){string kind=r.ReadString();bool filled=filledField&&r.ReadBoolean();var s=new VectorShape{Kind=kind,Filled=filled,Colour=Color.FromArgb(r.ReadInt32()),Width=r.ReadSingle(),Opacity=r.ReadSingle()};if(taperField)s.Taper=r.ReadSingle();if(float.IsNaN(s.Taper)||s.Taper<0||s.Taper>100)throw new InvalidDataException("Invalid taper");int n=r.ReadInt32();if((s.Kind!="Compound"&&s.Kind!="Text"&&s.Kind!="Polyline"&&s.Kind!="Line"&&s.Kind!="Ellipse"&&s.Kind!="Polygon"&&s.Kind!="Curvature pen"&&s.Kind!="Closed curve")||n<2||n>10000||float.IsNaN(s.Width)||s.Width<.25f||s.Width>500||float.IsNaN(s.Opacity)||s.Opacity<0||s.Opacity>1)throw new InvalidDataException("Invalid vector shape");for(int i=0;i<n;i++){float x=r.ReadSingle(),y=r.ReadSingle();if(float.IsNaN(x)||float.IsNaN(y)||Math.Abs(x)>100000||Math.Abs(y)>100000)throw new InvalidDataException("Invalid vector point");s.Points.Add(new PointF(x,y));}if(handlesField)s.ReadHandles(r);return s;}
}
partial class Layer {
 public List<VectorShape> Vectors=new List<VectorShape>();Bitmap rendered;
 public void InvalidateVectors(){InvalidateAdjustment();if(rendered!=null){rendered.Dispose();rendered=null;}}
 public Bitmap Rendered(){return Display(RawRendered());}public Bitmap RawRendered(){if(Is3D){if(rendered==null)rendered=Scene.Render(Image.Width,Image.Height);return rendered;}if(Vectors.Count==0)return Image;if(rendered==null){rendered=(Bitmap)Image.Clone();using(var g=Graphics.FromImage(rendered)){g.SmoothingMode=SmoothingMode.AntiAlias;foreach(var v in Vectors)v.Draw(g);}}return rendered;}
 public void UpdateVectorRegion(RectangleF area){MarkVisual(Rectangle.Ceiling(area));if(rendered==null){InvalidateAdjustment();return;}Rectangle rect=Rectangle.Intersect(Rectangle.Ceiling(area),new Rectangle(0,0,Image.Width,Image.Height));if(rect.IsEmpty)return;using(var g=Graphics.FromImage(rendered)){g.SetClip(rect);g.CompositingMode=CompositingMode.SourceCopy;g.DrawImage(Image,rect,rect,GraphicsUnit.Pixel);g.CompositingMode=CompositingMode.SourceOver;g.SmoothingMode=SmoothingMode.AntiAlias;foreach(var v in Vectors)if(v.Bounds().IntersectsWith(area))v.Draw(g);}PatchAdjustment(rendered,rect);}
 public List<VectorShape> CopyVectors(){return Vectors.ConvertAll(v=>v.Copy());}
}
partial class Canvas {
 public int PolygonSides=6;PointF polygonCentre;bool vectorChanged;public float VectorWidth=5,VectorOpacity=1;public Action VectorSelected;public string VectorMode="Brushes";VectorShape draft,selectedVector;int vectorHandle=-2;PointF vectorLast;bool vectorDragging;
 public void CancelVector(){freehandPoints=null;draft=null;selectedVector=null;ClearSelectedPaths();VectorBoxMode=false;vectorBoxDragging=false;NotifyVectorBox();selectedPoints.Clear();NotifyPointSelection();vectorHandle=-2;vectorDragging=false;vectorChanged=false;Invalidate();}
 bool VectorDown(PointF p){if(VectorMode!="Select/edit")p=SnapVectorPoint(p);if(VectorMode=="Brushes"||!Doc.Selected.IsVector)return false;if(!Doc.Selected.Visible||Doc.Selected.IsLocked)return true;
  if(VectorMode=="Text"){if(TextRequested!=null)TextRequested(p,null);return true;}if(VectorMode=="Vector pen"){BeginVectorPen(p);return true;}if(VectorMode=="Select/edit")return PickVector(p,ModifierKeys);if(VectorMode=="Freehand"){StartVectorFreehand(p,ModifierKeys);return true;}
  if((VectorMode=="Curvature pen"||VectorMode=="Polyline")&&draft!=null){if(StrokeSession.Distance(p,draft.Points[draft.Points.Count-1])>.001f)draft.Points.Add(p);Invalidate();return true;}
  draft=new VectorShape{CornerRadius=VectorRadius,Kind=VectorMode=="Rectangle"?"Polygon":VectorMode,Colour=Ink,Width=VectorWidth,Opacity=VectorOpacity,Taper=VectorMode=="Rectangle"||VectorMode=="Polygon"?0:VectorTaper,Fill=VectorFill.Copy()};polygonCentre=p;draft.Points.Add(p);if(VectorMode!="Curvature pen"&&VectorMode!="Polyline"){draft.Points.Add(p);vectorDragging=true;vectorChanged=false;Capture=true;}Invalidate();return true;
 }
 static List<PointF> RegularPolygon(PointF centre,PointF edge,int sides){double radius=StrokeSession.Distance(centre,edge),angle=Math.Atan2(edge.Y-centre.Y,edge.X-centre.X);var points=new List<PointF>();for(int i=0;i<sides;i++){double a=angle+2*Math.PI*i/sides;points.Add(new PointF(centre.X+(float)(radius*Math.Cos(a)),centre.Y+(float)(radius*Math.Sin(a))));}return points;}
 void InvalidateVectorArea(RectangleF bounds){bounds.Inflate(50/Zoom,50/Zoom);PointF a=ScreenPoint(bounds.Location);Invalidate(Rectangle.FromLTRB((int)Math.Floor(a.X)-2,(int)Math.Floor(a.Y)-2,(int)Math.Ceiling(a.X+bounds.Width*Zoom)+2,(int)Math.Ceiling(a.Y+bounds.Height*Zoom)+2));}
 bool VectorMove(PointF p){if(VectorMode!="Select/edit"||vectorDragging)p=SnapVectorPoint(p);if(VectorMode=="Brushes")return false;if(!vectorDragging)return true;p=ConstrainPointAxis(p);
  if(VectorMode=="Vector pen"&&draft!=null){MoveVectorPen(p);return true;}if(freehandPoints!=null){MoveVectorFreehand(p);return true;}if(draft!=null){RectangleF before=draft.Bounds();if(VectorMode=="Rectangle"){draft.Points=RectanglePoints(polygonCentre,p,(ModifierKeys&Keys.Shift)!=0);}else if(VectorMode=="Polygon"){draft.Points=AlignedPolygon(polygonCentre,p,PolygonSides,ModifierKeys);}else{if(draft.Kind=="Ellipse"&&(ModifierKeys&Keys.Shift)!=0){var a=draft.Points[0];float side=Math.Max(Math.Abs(p.X-a.X),Math.Abs(p.Y-a.Y));p=new PointF(a.X+(p.X<a.X?-1:1)*side,a.Y+(p.Y<a.Y?-1:1)*side);}draft.Points[1]=p;}InvalidateVectorArea(RectangleF.Union(before,draft.Bounds()));}
  else if(selectedVector!=null&&StrokeSession.Distance(p,vectorLast)>.001f){RectangleF before=SelectedPathsBounds();if(!vectorChanged){if(BeforeStroke!=null)BeforeStroke();if(duplicateVectorOnDrag){DuplicateDraggedVectors();duplicateVectorOnDrag=false;}vectorChanged=true;}if(selectedVector.Kind=="Ellipse"&&(vectorHandle>=0||vectorHandle==-4))ConvertSelectedEllipse();if(vectorHandle==-4){selectedVector.SetPointHandle(curveHandlePoint,curveHandleSide,p,(ModifierKeys&Keys.Alt)!=0);}else if(vectorHandle==-3){PointF c=selectedVector.CentrePoint();double angle=(Math.Atan2(p.Y-c.Y,p.X-c.X)-Math.Atan2(vectorLast.Y-c.Y,vectorLast.X-c.X))*180/Math.PI;selectedVector.Rotate((float)angle);}else if(vectorHandle>=0){if(selectedVector.Kind!="Ellipse"&&selectedPoints.Count>1){foreach(int index in selectedPoints.Where(i=>i>=0&&i<selectedVector.Points.Count)){var point=selectedVector.Points[index];selectedVector.Points[index]=new PointF(point.X+p.X-vectorLast.X,point.Y+p.Y-vectorLast.Y);}}else selectedVector.SetGrip(vectorHandle,p);}else foreach(var shape in selectedPaths)for(int i=0;i<shape.Points.Count;i++)shape.Points[i]=new PointF(shape.Points[i].X+p.X-vectorLast.X,shape.Points[i].Y+p.Y-vectorLast.Y);vectorLast=p;var area=RectangleF.Union(before,SelectedPathsBounds());Doc.Selected.UpdateVectorRegion(area);InvalidateVectorArea(area);}return true;
 }
 bool VectorUp(PointF p){if(VectorMode!="Select/edit"||vectorDragging)p=SnapVectorPoint(p);if(VectorMode=="Vector pen"&&draft!=null){if(vectorDragging)MoveVectorPen(p);vectorDragging=false;Capture=false;return true;}if(freehandPoints!=null){FinishVectorFreehand(p);return true;}if(VectorMode=="Brushes")return false;VectorMove(p);if(vectorDragging){vectorDragging=false;Capture=false;if(draft!=null)FinishVector();else if(vectorChanged&&AfterStroke!=null)AfterStroke();vectorChanged=false;}return true;}
 public void ChangeVectorWeight(float width){if(Doc!=null&&Doc.Selected.IsLocked)return;VectorWidth=width;if(selectedVector==null||Doc==null||!Doc.Selected.Vectors.Contains(selectedVector)||selectedVector.Width==width)return;if(BeforeStroke!=null)BeforeStroke();var old=selectedVector.Bounds();selectedVector.Width=width;Doc.Selected.UpdateVectorRegion(RectangleF.Union(old,selectedVector.Bounds()));if(AfterStroke!=null)AfterStroke();InvalidateVectorArea(RectangleF.Union(old,selectedVector.Bounds()));}
 public void ChangePolygonSides(int sides){if(Doc!=null&&Doc.Selected.IsLocked)return;sides=Math.Max(3,Math.Min(20,sides));PolygonSides=sides;if(selectedVector==null||selectedVector.Kind!="Polygon"||Doc==null||!Doc.Selected.Vectors.Contains(selectedVector)||selectedVector.Points.Count==sides)return;PointF centre=PointF.Empty;foreach(var p in selectedVector.Points){centre.X+=p.X;centre.Y+=p.Y;}centre.X/=selectedVector.Points.Count;centre.Y/=selectedVector.Points.Count;if(BeforeStroke!=null)BeforeStroke();var old=selectedVector.Bounds();selectedVector.Handles.Clear();selectedVector.Points=RegularPolygon(centre,selectedVector.Points[0],sides);selectedPoints.Clear();NotifyPointSelection();Doc.Selected.UpdateVectorRegion(RectangleF.Union(old,selectedVector.Bounds()));if(AfterStroke!=null)AfterStroke();InvalidateVectorArea(RectangleF.Union(old,selectedVector.Bounds()));}
 public void FinishVector(){if(Doc!=null&&Doc.Selected.IsLocked){CancelVector();return;}if(draft==null||Doc==null||!Doc.Selected.IsVector)return;if(draft.Points.Count<(draft.Kind=="Polygon"?3:2))return;if(draft.Kind!="Polygon"&&StrokeSession.Distance(draft.Points[0],draft.Points[1])<1){draft=null;return;}if(BeforeStroke!=null)BeforeStroke();AddSymmetricVectors(draft);selectedVector=draft;ClearSelectedPaths();AddSelectedPath(draft);selectedPoints.Clear();NotifyPointSelection();draft=null;Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();Invalidate();}
 public VectorShape SelectedVector {get{return selectedVector;}}
 public void ApplyVectorStyle(){if(Doc!=null&&Doc.Selected.IsLocked)return;if(Doc==null||selectedVector==null||!Doc.Selected.Vectors.Contains(selectedVector))return;if(BeforeStroke!=null)BeforeStroke();foreach(var shape in selectedPaths){shape.Colour=Ink;shape.Width=VectorWidth;shape.Opacity=VectorOpacity;}Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();Invalidate();}
 public void DeleteVector(){if(Doc!=null&&Doc.Selected.IsLocked)return;if(selectedVector==null||Doc==null||!Doc.Selected.Vectors.Contains(selectedVector))return;if(BeforeStroke!=null)BeforeStroke();foreach(var shape in selectedPaths)Doc.Selected.Vectors.Remove(shape);ClearSelectedPaths();selectedVector=null;selectedPoints.Clear();NotifyPointSelection();Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();Invalidate();}
 PointF VectorRotationGrip(){var b=selectedVector.Bounds();return new PointF(b.Left+b.Width/2,b.Top-30/Zoom);}
 void PaintVectors(Graphics g){if(TransformMode!=null)return;var state=g.Save();g.TranslateTransform(Offset.X,Offset.Y);g.ScaleTransform(Zoom,Zoom);g.SetClip(new Rectangle(0,0,Doc.Width,Doc.Height));g.SmoothingMode=SmoothingMode.AntiAlias;PaintPathSelection(g);PaintVectorPenDraft(g);if(draft!=null){draft.Draw(g);if(freehandPoints==null&&(draft.Kind=="Polygon"||draft.Kind=="Curvature pen"||draft.Kind=="Polyline"))foreach(var p in draft.Points)g.FillEllipse(Brushes.Teal,p.X-3/Zoom,p.Y-3/Zoom,6/Zoom,6/Zoom);}if(VectorMode=="Select/edit"&&selectedVector!=null&&selectedPaths.Count==1&&Doc.Selected.Vectors.Contains(selectedVector)){PaintPointHandles(g);var grips=selectedVector.Grips();for(int index=0;index<grips.Length;index++){var p=grips[index];g.FillRectangle(selectedPoints.Contains(index)?Brushes.Teal:Brushes.White,p.X-4/Zoom,p.Y-4/Zoom,8/Zoom,8/Zoom);using(var pen=new Pen(Color.Teal,1/Zoom))g.DrawRectangle(pen,p.X-4/Zoom,p.Y-4/Zoom,8/Zoom,8/Zoom);}var r=VectorRotationGrip();using(var pen=new Pen(Color.Teal,1/Zoom)){var bounds=selectedVector.Bounds();g.DrawLine(pen,new PointF(r.X,bounds.Top),r);g.FillEllipse(Brushes.White,r.X-10/Zoom,r.Y-10/Zoom,20/Zoom,20/Zoom);g.DrawArc(pen,r.X-7/Zoom,r.Y-7/Zoom,14/Zoom,14/Zoom,30,290);g.DrawLine(pen,r.X+6/Zoom,r.Y-4/Zoom,r.X+9/Zoom,r.Y-8/Zoom);}}g.Restore(state);}
 PointF straightStart,straightEnd;bool straightDragging;
 public void ResetShift(){straightDragging=false;Invalidate();}
 void BeginStraight(PointF p){straightStart=straightEnd=p;straightDragging=true;Capture=true;Invalidate();}
 void FinishStraight(PointF end){if(!straightDragging)return;straightDragging=false;Capture=false;if(Doc==null||Doc.Selected.IsVector||Doc.Selected.IsLocked||!Doc.Selected.Visible)return;if(BeforeStroke!=null)BeforeStroke();var line=new StrokeSession(Doc.Selected.Image,Tool,Ink,BrushSize,BrushOpacity,straightStart,SimulatePressure,false,1,TaperPercent,new SymmetryMap(Doc.Width,Doc.Height,VerticalMirror,HorizontalMirror,RadialSymmetry,RadialRepeats),BrushFlow,BrushHardness,SelectionMask);line.Move(end);line.Finish();if(AfterStroke!=null)AfterStroke();Invalidate();}
 void PaintStraight(Graphics g){if(!straightDragging)return;PointF a=ScreenPoint(straightStart),b=ScreenPoint(straightEnd);using(var p=new Pen(Ink,Math.Max(1,BrushSize*Zoom))){p.DashStyle=DashStyle.Dash;g.DrawLine(p,a,b);}}
 public void TestStraightDrag(Point a,Point b){BeginStraight(Pixel(a));OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,b.X,b.Y,0));OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,b.X,b.Y,0));}
}
